mapper.update:
UPDATE safety_spot_check_record R
  JOIN safety_spot_check_device_info D ON D.ID = R.DEVICE_ID
   SET R.plan_check_emp_no = D.check_emp_no,
       R.plan_check_emp = D.check_emp
 WHERE R.device_id in

  #{item}

   and R.`status` = #{status}

   AND R.task_begin_date<=#{spotEndDate}
   AND R.task_end_date>=#{spotEndDate}

UPDATE safety_spot_check_record R
JOIN safety_spot_check_device_info D ON D.ID = R.DEVICE_ID
SET R.plan_check_emp_no = D.check_emp_no,
    R.plan_check_emp = D.check_emp
WHERE R.device_id in

  #{item}

and R.`status` = #{status}

   AND R.task_begin_date >= #{spotEndDate}

if.foreach:
update safety_spot_check_record
set
    task_id = #{latestTaskId}
where
    id = #{id}
